import sys
import os
import json

def parse_file(filepath):
    if not os.path.exists(filepath):
        return []
    with open(filepath, 'r') as f:
        content = f.read()
    lines = content.splitlines()
    header = None
    rows = []
    for line in lines:
        if not line.strip():
            continue
        if line.startswith('#'):
            continue
        if header is None:
            header = line.split('|')
            continue
        fields = line.split('|')
        row = dict(zip(header, fields))
        rows.append(row)
    return rows

def convert_date(date_str):
    parts = date_str.strip().split('/')
    if len(parts) != 3:
        return None
    m, d, y = parts
    return f"{y}-{int(m):02d}-{int(d):02d}"

def get_fact(by_entity, entity, column):
    rows = by_entity.get(entity, [])
    values = []
    for row in rows:
        val = row.get(column, '')
        if val and val.strip():
            converted = convert_date(val.strip())
            if converted:
                values.append(converted)
            else:
                values.append(val.strip())
    if not values:
        return None, False
    distinct = set(values)
    if len(distinct) > 1:
        return None, True
    return values[0], False

def resolve(primary, primary_col, fallback, fallback_col, entity, primary_name, fallback_name):
    val, conflict = get_fact(primary, entity, primary_col)
    if conflict:
        return "CONFLICT"
    if val is not None:
        return [val, primary_name]
    if fallback is not None and fallback_col is not None:
        val, conflict = get_fact(fallback, entity, fallback_col)
        if conflict:
            return "CONFLICT"
        if val is not None:
            return [val, fallback_name]
    return "ABSENT"

def main():
    directory = sys.argv[1]

    file_specs = {
        'work_authorizations': 'work_authorizations.txt',
        'ead_cards': 'ead_cards.txt',
        'reverifications': 'reverifications.txt',
        'lca_notices': 'lca_notices.txt',
        'lca_filings': 'lca_filings.txt',
        'dol_receipts': 'dol_receipts.txt',
    }

    data = {}
    for name, filename in file_specs.items():
        filepath = os.path.join(directory, filename)
        rows = parse_file(filepath)
        by_entity = {}
        for row in rows:
            wfn = row.get('WORKER_FILE_NUMBER', '').strip()
            if wfn:
                by_entity.setdefault(wfn, []).append(row)
        data[name] = by_entity

    entities = [f"E-401{i:02d}" for i in range(1, 17)]

    result = {}

    for entity in entities:
        pair_id = f"wf.reverify_window::{entity}"
        result[pair_id] = {
            "authorization expiry": resolve(
                data['work_authorizations'], 'EMPLOYABILITY_EVIDENCE_LAPSE',
                data['ead_cards'], 'I766_VALID_TO',
                entity, 'work_authorizations', 'ead_cards'
            ),
            "reverification date": resolve(
                data['reverifications'], 'SUPPLEMENT_B_EXECUTED',
                None, None,
                entity, 'reverifications', None
            )
        }

        pair_id = f"wf.notice_posting::{entity}"
        result[pair_id] = {
            "notice posted": resolve(
                data['lca_notices'], 'NOTICE_DISPLAY_BEGIN',
                None, None,
                entity, 'lca_notices', None
            ),
            "notice removed": resolve(
                data['lca_notices'], 'NOTICE_DISPLAY_END',
                None, None,
                entity, 'lca_notices', None
            ),
            "LCA filed": resolve(
                data['lca_filings'], 'ETA9035_SUBMISSION_DAY',
                data['dol_receipts'], 'OFLC_INTAKE_DAY',
                entity, 'lca_filings', 'dol_receipts'
            )
        }

    print(json.dumps(result, indent=2))

if __name__ == '__main__':
    main()
