import json
import re
import sys
import os

MONTHS = {
    'jan': 1, 'january': 1,
    'feb': 2, 'february': 2,
    'mar': 3, 'march': 3,
    'apr': 4, 'april': 4,
    'may': 5,
    'jun': 6, 'june': 6,
    'jul': 7, 'july': 7,
    'aug': 8, 'august': 8,
    'sep': 9, 'sept': 9, 'september': 9,
    'oct': 10, 'october': 10,
    'nov': 11, 'november': 11,
    'dec': 12, 'december': 12,
}

def parse_date(text):
    if text is None:
        return None
    m = re.search(r'([A-Za-z]+)\.?\s+(\d+),\s+(\d{4})', text)
    if m:
        month_name = m.group(1).lower()
        day = int(m.group(2))
        year = int(m.group(3))
        month = MONTHS.get(month_name)
        if month:
            return f"{year:04d}-{month:02d}-{day:02d}"
    return None

def parse_html_file(filepath):
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()

    sheets = []
    sheet_pattern = re.compile(r'<article class="sheet"[^>]*>(.*?)</article>', re.DOTALL)
    for sheet_match in sheet_pattern.finditer(content):
        sheet_content = sheet_match.group(1)

        rows = {}
        row_pattern = re.compile(r'<tr><th>(.*?)</th><td([^>]*)>(.*?)</td></tr>', re.DOTALL)
        for row_match in row_pattern.finditer(sheet_content):
            caption = row_match.group(1).strip()
            td_attrs = row_match.group(2)
            value_html = row_match.group(3).strip()

            if 'class="void"' in td_attrs:
                value = None
            else:
                value = re.sub(r'<[^>]+>', '', value_html).strip()
                if not value:
                    value = None
            rows[caption] = value

        badge = rows.get('Staff badge')
        if badge:
            sheets.append((badge, rows))

    return sheets

def collect_values(sheets, caption):
    values = {}
    for badge, rows in sheets:
        value = rows.get(caption)
        if value is not None:
            parsed = parse_date(value)
            if badge not in values:
                values[badge] = set()
            values[badge].add(parsed if parsed else value)
    return values

def get_value(values_dict, entity, doc_name):
    if entity not in values_dict:
        return "ABSENT"
    vals = values_dict[entity]
    if len(vals) == 1:
        return [list(vals)[0], doc_name]
    else:
        return "CONFLICT"

def get_value_with_fallback(primary_dict, fallback_dict, entity, primary_doc, fallback_doc):
    if entity in primary_dict:
        vals = primary_dict[entity]
        if len(vals) == 1:
            return [list(vals)[0], primary_doc]
        else:
            return "CONFLICT"
    else:
        return get_value(fallback_dict, entity, fallback_doc)

def main():
    directory = sys.argv[1]

    work_auth_sheets = parse_html_file(os.path.join(directory, 'work_authorizations.html'))
    ead_cards_sheets = parse_html_file(os.path.join(directory, 'ead_cards.html'))
    reverifications_sheets = parse_html_file(os.path.join(directory, 'reverifications.html'))
    lca_notices_sheets = parse_html_file(os.path.join(directory, 'lca_notices.html'))
    lca_filings_sheets = parse_html_file(os.path.join(directory, 'lca_filings.html'))
    dol_receipts_sheets = parse_html_file(os.path.join(directory, 'dol_receipts.html'))

    work_auth_expiry = collect_values(work_auth_sheets, 'Evidence expires')
    ead_expiry = collect_values(ead_cards_sheets, 'EAD valid to')
    reverify_date = collect_values(reverifications_sheets, 'Supplement B signed on')
    notice_posted = collect_values(lca_notices_sheets, 'Notice first displayed')
    notice_removed = collect_values(lca_notices_sheets, 'Notice withdrawn from display')
    lca_filed = collect_values(lca_filings_sheets, 'Submitted through FLAG')
    dol_receipt = collect_values(dol_receipts_sheets, 'Agency receipt notice dated')

    entities = [f'E-4010{i:02d}' for i in range(1, 17)]

    result = {}

    for entity in entities:
        reverify_key = f'wf.reverify_window::{entity}'
        result[reverify_key] = {}
        result[reverify_key]['authorization expiry'] = get_value_with_fallback(
            work_auth_expiry, ead_expiry, entity, 'work_authorizations', 'ead_cards')
        result[reverify_key]['reverification date'] = get_value(
            reverify_date, entity, 'reverifications')

    for entity in entities:
        notice_key = f'wf.notice_posting::{entity}'
        result[notice_key] = {}
        result[notice_key]['notice posted'] = get_value(
            notice_posted, entity, 'lca_notices')
        result[notice_key]['notice removed'] = get_value(
            notice_removed, entity, 'lca_notices')
        result[notice_key]['LCA filed'] = get_value_with_fallback(
            lca_filed, dol_receipt, entity, 'lca_filings', 'dol_receipts')

    print(json.dumps(result, indent=2))

if __name__ == '__main__':
    main()
