import sys
import os
import re
import json
from html.parser import HTMLParser

MONTHS = {
    'Jan': 1, 'January': 1,
    'Feb': 2, 'February': 2,
    'Mar': 3, 'March': 3,
    'Apr': 4, 'April': 4,
    'May': 5,
    'Jun': 6, 'June': 6,
    'Jul': 7, 'July': 7,
    'Aug': 8, 'August': 8,
    'Sep': 9, 'Sept': 9, 'September': 9,
    'Oct': 10, 'October': 10,
    'Nov': 11, 'November': 11,
    'Dec': 12, 'December': 12,
}

def parse_date(text):
    m = re.search(r'(?:[A-Za-z]+\.,\s*)?([A-Za-z]+)\.?\s+(\d+),\s+(\d{4})', text)
    if not m:
        return None
    month_name = m.group(1)
    day = int(m.group(2))
    year = int(m.group(3))
    month = MONTHS.get(month_name)
    if month is None:
        return None
    return f"{year:04d}-{month:02d}-{day:02d}"

class SheetParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.sheets = []
        self.current_sheet = None
        self.in_table = False
        self.in_th = False
        self.in_td = False
        self.current_th = None
        self.current_td_content = []
        self.td_is_void = False

    def handle_starttag(self, tag, attrs):
        attrs_dict = dict(attrs)
        classes = attrs_dict.get('class', '').split()
        if tag == 'article' and 'sheet' in classes:
            self.current_sheet = {}
        elif tag == 'table' and 'fields' in classes:
            self.in_table = True
        elif tag == 'th' and self.in_table:
            self.in_th = True
            self.current_th = []
        elif tag == 'td' and self.in_table:
            self.in_td = True
            self.current_td_content = []
            self.td_is_void = 'void' in classes

    def handle_endtag(self, tag):
        if tag == 'article' and self.current_sheet is not None:
            self.sheets.append(self.current_sheet)
            self.current_sheet = None
        elif tag == 'table' and self.in_table:
            self.in_table = False
        elif tag == 'th' and self.in_th:
            self.in_th = False
            self.current_th = ''.join(self.current_th).strip()
        elif tag == 'td' and self.in_td:
            self.in_td = False
            value = ''.join(self.current_td_content).strip()
            if self.td_is_void:
                value = None
            if self.current_th is not None and self.current_sheet is not None:
                self.current_sheet[self.current_th] = value
            self.current_th = None

    def handle_data(self, data):
        if self.in_th:
            self.current_th.append(data)
        elif self.in_td:
            self.current_td_content.append(data)

def extract_values(filepath, badge_field, value_field):
    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            html = f.read()
    except OSError:
        return {}

    parser = SheetParser()
    parser.feed(html)

    result = {}
    for sheet in parser.sheets:
        badge = sheet.get(badge_field)
        if not badge:
            continue
        value = sheet.get(value_field)
        if value is None or value == '':
            continue
        parsed = parse_date(value)
        if parsed is None:
            parsed = value
        if badge not in result:
            result[badge] = []
        result[badge].append(parsed)

    return result

def get_fact_value(doc_data, badge, sources):
    for filename, badge_field, value_field in sources:
        key = (filename, value_field)
        if badge in doc_data.get(key, {}):
            values = doc_data[key][badge]
            if len(set(values)) > 1:
                return "CONFLICT"
            elif len(values) > 0:
                doc_name = filename.replace('.html', '')
                return [values[0], doc_name]
    return "ABSENT"

def main():
    directory = sys.argv[1]

    facts_config = {
        'wf.reverify_window': {
            'authorization expiry': [
                ('work_authorizations.html', 'Staff badge', 'Evidence expires'),
                ('ead_cards.html', 'Staff badge', 'EAD valid to'),
            ],
            'reverification date': [
                ('reverifications.html', 'Staff badge', 'Supplement B signed on'),
            ],
        },
        'wf.notice_posting': {
            'notice posted': [
                ('lca_notices.html', 'Staff badge', 'Notice first displayed'),
            ],
            'notice removed': [
                ('lca_notices.html', 'Staff badge', 'Notice withdrawn from display'),
            ],
            'LCA filed': [
                ('lca_filings.html', 'Staff badge', 'Submitted through FLAG'),
                ('dol_receipts.html', 'Staff badge', 'Agency receipt notice dated'),
            ],
        },
    }

    doc_data = {}
    for rule_name, facts in facts_config.items():
        for fact_name, sources in facts.items():
            for filename, badge_field, value_field in sources:
                key = (filename, value_field)
                if key not in doc_data:
                    filepath = os.path.join(directory, filename)
                    doc_data[key] = extract_values(filepath, badge_field, value_field)

    pairs = []
    for i in range(1, 17):
        badge = f'E-402{i:02d}'
        pairs.append(('wf.reverify_window', badge))
    for i in range(1, 17):
        badge = f'E-402{i:02d}'
        pairs.append(('wf.notice_posting', badge))

    output = {}
    for rule_name, badge in pairs:
        pair_id = f"{rule_name}::{badge}"
        output[pair_id] = {}
        for fact_name, sources in facts_config[rule_name].items():
            output[pair_id][fact_name] = get_fact_value(doc_data, badge, sources)

    print(json.dumps(output, indent=2))

if __name__ == '__main__':
    main()
