import sys
import os
import re
import json
from datetime import date, timedelta

def parse_tuples(s):
    tuples = []
    i = 0
    while i < len(s):
        while i < len(s) and s[i] != '(':
            i += 1
        if i >= len(s):
            break
        i += 1
        current = ''
        in_string = False
        while i < len(s):
            c = s[i]
            if c == "'":
                if in_string and i + 1 < len(s) and s[i+1] == "'":
                    current += "''"
                    i += 2
                    continue
                in_string = not in_string
                current += c
            elif c == ')' and not in_string:
                tuples.append(current)
                i += 1
                break
            else:
                current += c
            i += 1
    return tuples

def split_sql_values(s):
    values = []
    current = ''
    in_string = False
    i = 0
    while i < len(s):
        c = s[i]
        if c == "'":
            if in_string and i + 1 < len(s) and s[i+1] == "'":
                current += "''"
                i += 2
                continue
            in_string = not in_string
            current += c
        elif c == ',' and not in_string:
            values.append(current.strip())
            current = ''
        else:
            current += c
        i += 1
    if current.strip():
        values.append(current.strip())
    return values

def parse_sql_value(val_str):
    val_str = val_str.strip()
    if val_str.upper() == 'NULL':
        return None
    if val_str.startswith("'") and val_str.endswith("'"):
        return val_str[1:-1]
    try:
        return int(val_str)
    except ValueError:
        return val_str

def parse_sql_file(content):
    records = []
    insert_re = re.compile(
        r'INSERT\s+INTO\s+\w+\s*\(([^)]+)\)\s*VALUES\s*(.*?);',
        re.IGNORECASE | re.DOTALL
    )
    for m in insert_re.finditer(content):
        cols_str = m.group(1)
        vals_str = m.group(2)
        columns = [c.strip() for c in cols_str.split(',')]
        tuple_strs = parse_tuples(vals_str)
        for tuple_str in tuple_strs:
            raw_vals = split_sql_values(tuple_str)
            record = {}
            for col, val in zip(columns, raw_vals):
                record[col] = parse_sql_value(val)
            records.append(record)
    return records

def epd_to_date(epd):
    return (date(1970, 1, 1) + timedelta(days=epd)).isoformat()

def get_values_for_worker(records, wkr_code, value_col):
    values = []
    for r in records:
        if r.get('wkr_code') == wkr_code:
            v = r.get(value_col)
            if v is not None:
                values.append(v)
    return values

def resolve_fact(primary_records, primary_col, wkr_code, primary_doc,
                  fallback_records=None, fallback_col=None, fallback_doc=None):
    values = get_values_for_worker(primary_records, wkr_code, primary_col)
    if values:
        if len(set(values)) > 1:
            return "CONFLICT"
        return [epd_to_date(values[0]), primary_doc]
    if fallback_records is not None and fallback_col is not None:
        values = get_values_for_worker(fallback_records, wkr_code, fallback_col)
        if values:
            if len(set(values)) > 1:
                return "CONFLICT"
            return [epd_to_date(values[0]), fallback_doc]
    return "ABSENT"

def main():
    dir_path = sys.argv[1]
    docs = {}
    for fname in os.listdir(dir_path):
        if fname.endswith('.sql'):
            doc_name = fname[:-4]
            with open(os.path.join(dir_path, fname), 'r', encoding='utf-8') as f:
                content = f.read()
            docs[doc_name] = parse_sql_file(content)

    all_workers = set()
    for records in docs.values():
        for r in records:
            if 'wkr_code' in r:
                all_workers.add(r['wkr_code'])
    workers = sorted(all_workers)

    reverify_facts = {
        'authorization expiry': {
            'primary': ('work_authorizations', 'eligibility_doc_lapse_epd'),
            'fallback': ('ead_cards', 'ead_lapse_epd'),
        },
        'reverification date': {
            'primary': ('reverifications', 'i9_redo_done_epd'),
            'fallback': None,
        },
    }

    notice_facts = {
        'notice posted': {
            'primary': ('lca_notices', 'board_pinned_epd'),
            'fallback': None,
        },
        'notice removed': {
            'primary': ('lca_notices', 'board_unpinned_epd'),
            'fallback': None,
        },
        'LCA filed': {
            'primary': ('lca_filings', 'lca_lodge_epd'),
            'fallback': ('dol_receipts', 'agency_stamp_epd'),
        },
    }

    result = {}

    for wkr in workers:
        pair_id = f'wf.reverify_window::{wkr}'
        result[pair_id] = {}
        for fact_name, config in reverify_facts.items():
            p_doc, p_col = config['primary']
            if config['fallback']:
                f_doc, f_col = config['fallback']
                result[pair_id][fact_name] = resolve_fact(
                    docs.get(p_doc, []), p_col, wkr, p_doc,
                    docs.get(f_doc, []), f_col, f_doc
                )
            else:
                result[pair_id][fact_name] = resolve_fact(
                    docs.get(p_doc, []), p_col, wkr, p_doc
                )

    for wkr in workers:
        pair_id = f'wf.notice_posting::{wkr}'
        result[pair_id] = {}
        for fact_name, config in notice_facts.items():
            p_doc, p_col = config['primary']
            if config['fallback']:
                f_doc, f_col = config['fallback']
                result[pair_id][fact_name] = resolve_fact(
                    docs.get(p_doc, []), p_col, wkr, p_doc,
                    docs.get(f_doc, []), f_col, f_doc
                )
            else:
                result[pair_id][fact_name] = resolve_fact(
                    docs.get(p_doc, []), p_col, wkr, p_doc
                )

    print(json.dumps(result))

if __name__ == '__main__':
    main()
