#!/usr/bin/env python3
import sys
import os
import re
import json
from datetime import date, timedelta

def parse_values(s):
    """Parse a comma-separated list of SQL values."""
    values = []
    i = 0
    while i < len(s):
        while i < len(s) and s[i] in ' \t\n':
            i += 1
        if i >= len(s):
            break
        if s[i] == "'":
            i += 1
            start = i
            while i < len(s):
                if s[i] == "'":
                    if i + 1 < len(s) and s[i + 1] == "'":
                        i += 2
                        continue
                    break
                i += 1
            values.append(s[start:i])
            i += 1
        else:
            start = i
            while i < len(s) and s[i] != ',':
                i += 1
            val = s[start:i].strip()
            if val.upper() == 'NULL':
                values.append(None)
            else:
                values.append(val)
        while i < len(s) and s[i] in ' \t\n':
            i += 1
        if i < len(s) and s[i] == ',':
            i += 1
    return values

def parse_sql_file(content):
    """Parse SQL file and return dict mapping table_name -> list of row dicts."""
    tables = {}
    insert_pattern = re.compile(
        r'INSERT\s+INTO\s+(\w+)\s*\(([^)]+)\)\s*VALUES\s*(.*?);',
        re.IGNORECASE | re.DOTALL
    )
    for match in insert_pattern.finditer(content):
        table_name = match.group(1)
        columns_str = match.group(2)
        values_section = match.group(3)
        columns = [c.strip() for c in columns_str.split(',')]
        tuples = []
        i = 0
        while i < len(values_section):
            while i < len(values_section) and values_section[i] in ' \t\n,':
                i += 1
            if i >= len(values_section):
                break
            if values_section[i] == '(':
                depth = 1
                i += 1
                start = i
                in_quote = False
                while i < len(values_section) and depth > 0:
                    if values_section[i] == "'" and not in_quote:
                        in_quote = True
                    elif values_section[i] == "'" and in_quote:
                        if i + 1 < len(values_section) and values_section[i + 1] == "'":
                            i += 1
                        else:
                            in_quote = False
                    elif values_section[i] == '(' and not in_quote:
                        depth += 1
                    elif values_section[i] == ')' and not in_quote:
                        depth -= 1
                    i += 1
                tuple_str = values_section[start:i - 1]
                vals = parse_values(tuple_str)
                row = dict(zip(columns, vals))
                tuples.append(row)
            else:
                i += 1
        if table_name not in tables:
            tables[table_name] = []
        tables[table_name].extend(tuples)
    return tables

def epd_to_date(epd):
    """Convert epoch day to YYYY-MM-DD string."""
    d = date(1970, 1, 1) + timedelta(days=int(epd))
    return d.isoformat()

def get_values_for_entity(records, wkr_code, value_col):
    """Get all non-NULL values for a given worker code and column."""
    values = []
    for row in records:
        if row.get('wkr_code') == wkr_code:
            val = row.get(value_col)
            if val is not None:
                values.append(val)
    return values

def resolve_fact(data, doc_name, table_name, wkr_code, value_col):
    """Resolve a fact from a document.
    Returns: (value, doc_name) or 'CONFLICT' or None (no value).
    """
    records = data.get(doc_name, {}).get(table_name, [])
    values = get_values_for_entity(records, wkr_code, value_col)
    if len(values) == 0:
        return None
    unique_values = set(values)
    if len(unique_values) == 1:
        return (list(unique_values)[0], doc_name)
    else:
        return 'CONFLICT'

