from collections import defaultdict

def parse_edi(filepath):
    with open(filepath, 'r') as f:
        content = f.read()

    raw_segments = content.split('~')
    segments = []
    for seg in raw_segments:
        seg = seg.strip()
        if seg:
            segments.append(seg)

    loops = []
    current_loop = []

    for seg in segments:
        parts = seg.split('*')
        tag = parts[0]

        if tag == 'LX':
            if current_loop:
                loops.append(current_loop)
            current_loop = []
        else:
            current_loop.append(parts)

    if current_loop:
        loops.append(current_loop)

    entity_data = defaultdict(list)

    for loop in loops:
        entity_id = None
        for parts in loop:
            if parts[0] == 'REF' and len(parts) >= 3 and parts[1] == 'EI':
                entity_id = parts[2]
                break

        if entity_id:
            entity_data[entity_id].append(loop)

    return entity_data

def get_dtp_value(loop, qualifier):
    for parts in loop:
        if parts[0] == 'DTP' and len(parts) >= 4 and parts[1] == qualifier and parts[2] == 'D8':
            return parts[3]
    return None

def extract_dtp_fact(entity_data, entity_id, qualifier):
    if entity_id not in entity_data:
        return None, False

    values = []
    for loop in entity_data[entity_id]:
        val = get_dtp_value(loop, qualifier)
        if val is not None:
            values.append(val)

    if not values:
        return None, False

    if len(set(values)) > 1:
        return None, True

    return values[0], False

def format_date(date_str):
    if len(date_str) == 8:
        return f"{date_str[:4]}-{date_str[4:6]}-{date_str[6:8]}"
    return date_str

def resolve_with_fallback(entity_id, primary_data, primary_doc, primary_qualifier,
                           fallback_data, fallback_doc, fallback_qualifier):
    val, conflict = extract_dtp_fact(primary_data, entity_id, primary_qualifier)
    if conflict:
        return 'CONFLICT'
    if val is not None:
        return [format_date(val), primary_doc]

    if fallback_data is not None:
        val, conflict = extract_dtp_fact(fallback_data, entity_id, fallback_qualifier)
        if conflict:
            return 'CONFLICT'
        if val is not None:
            return [format_date(val), fallback_doc]

    return 'ABSENT'

def main():
    dir_path = sys.argv[1]

    files = {
