        segments.append(parts)
    return segments


def parse_document(path):
    segments = parse_edi(path)
    loops = []
    current = None
    for parts in segments:
        tag = parts[0] if parts else ''
        if tag == 'LX':
            if current is not None:
                loops.append(current)
            current = []
            current.append(parts)
        elif current is not None:
