            if tag == 'REF' and len(parts) >= 3 and parts[1] == 'EI':
                entity = parts[2]
            elif tag == 'DTP' and len(parts) >= 4:
                vals.setdefault(('DTP', parts[1]), []).append(parts[3])
            elif tag == 'REF' and len(parts) >= 3:
                vals.setdefault(('REF', parts[1]), []).append(parts[2])
        if entity is not None:
            for key, vlist in vals.items():
                result.setdefault(entity, {}).setdefault(key, []).extend(vlist)
    return result


def format_date(ccyymmdd):
