import sys
import os
import json
from datetime import date, timedelta

def parse_week_date(s):
    parts = s.split('-W')
    year = int(parts[0])
    week_day = parts[1].split('-')
    week = int(week_day[0])
    day = int(week_day[1])
    jan4 = date(year, 1, 4)
    week1_monday = jan4 - timedelta(days=jan4.weekday())
    target = week1_monday + timedelta(weeks=week - 1, days=day - 1)
    return target.isoformat()

def read_tsv(path):
    with open(path, 'r', encoding='utf-8-sig') as f:
        content = f.read()
    lines = content.replace('\r\n', '\n').replace('\r', '\n').split('\n')
    data_lines = [l for l in lines if not l.startswith('#') and l.strip()]
    if not data_lines:
        return {}
    header = data_lines[0].split('\t')
    result = {}
    for line in data_lines[1:]:
        cols = line.split('\t')
        if len(cols) < 2:
            continue
        attr = cols[0]
        rec_dict = {}
        for i, val in enumerate(cols[1:]):
            if i + 1 < len(header):
                rec_name = header[i + 1]
                rec_dict[rec_name] = val
        result[attr] = rec_dict
    return result

def get_worker_values(doc_data, worker_key, attr):
    if 'worker.key' not in doc_data or attr not in doc_data:
        return []
    worker_row = doc_data['worker.key']
    attr_row = doc_data[attr]
    results = []
    for rec_name, wkey in worker_row.items():
        if wkey == worker_key and rec_name in attr_row:
            val = attr_row[rec_name]
            if val and val != '~':
                results.append((rec_name, val))
    return results

def extract_fact(doc_specs, worker_key):
    for doc_name, doc_data, attr_name in doc_specs:
        values = get_worker_values(doc_data, worker_key, attr_name)
        if values:
            distinct = set(v for _, v in values)
            if len(distinct) > 1:
                return "CONFLICT"
            val = values[0][1]
            if '-W' in val:
                val = parse_week_date(val)
            return [val, doc_name]
    return "ABSENT"

def main():
    dir_path = sys.argv[1]

    doc_names = ['dol_receipts', 'ead_cards', 'hr_roster', 'lca_filings', 'lca_notices', 'reverifications', 'work_authorizations']
