import sys
import os
import json
from datetime import datetime

def parse_tsv(filepath):
    with open(filepath, 'r') as f:
        lines = f.readlines()
    data_lines = [l for l in lines if not l.startswith('#') and l.strip()]
    if not data_lines:
        return {}
    rows = [line.rstrip('\n').split('\t') for line in data_lines]
    attr_dict = {}
    for row in rows[1:]:
        if not row or not row[0]:
            continue
        attr = row[0]
        attr_dict[attr] = row[1:]
    return attr_dict

def week_to_date(week_str):
    if not week_str or week_str == '~':
        return None
    dt = datetime.strptime(week_str, "%G-W%V-%u")
    return dt.strftime("%Y-%m-%d")

def get_worker_values(attr_dict, attr_name):
    worker_keys = attr_dict.get('worker.key', [])
    attr_vals = attr_dict.get(attr_name, [])
    result = {}
    for i, wk in enumerate(worker_keys):
        if wk == '~' or not wk:
            continue
        val = attr_vals[i] if i < len(attr_vals) else '~'
        result.setdefault(wk, []).append(val)
    return result

def resolve(primary_map, primary_doc, fallback_map, fallback_doc, worker):
    vals = primary_map.get(worker, [])
    real_vals = [v for v in vals if v and v != '~']
    if real_vals:
        if len(set(real_vals)) == 1:
            return [week_to_date(real_vals[0]), primary_doc]
        else:
            return "CONFLICT"
    if fallback_map is not None:
        vals = fallback_map.get(worker, [])
        real_vals = [v for v in vals if v and v != '~']
        if real_vals:
            if len(set(real_vals)) == 1:
                return [week_to_date(real_vals[0]), fallback_doc]
            else:
                return "CONFLICT"
    return "ABSENT"

def main():
    dirpath = sys.argv[1]

    def load(name):
        return parse_tsv(os.path.join(dirpath, name + '.tsv'))

    wa = load('work_authorizations')
    ead = load('ead_cards')
    rev = load('reverifications')
    lca_notices = load('lca_notices')
    lca_filings = load('lca_filings')
    dol = load('dol_receipts')

    wa_expiry = get_worker_values(wa, 'eligibility.doc.lapse.wk')
    ead_expiry = get_worker_values(ead, 'ead.lapse.wk')
    rev_done = get_worker_values(rev, 'i9.redo.done.wk')

    notice_pinned = get_worker_values(lca_notices, 'board.pinned.wk')
    notice_unpinned = get_worker_values(lca_notices, 'board.unpinned.wk')
    lca_lodge = get_worker_values(lca_filings, 'lca.lodge.wk')
    dol_stamp = get_worker_values(dol, 'agency.stamp.wk')

    all_workers = set()
    for doc in [wa, ead, rev, lca_notices, lca_filings, dol]:
        for wk in doc.get('worker.key', []):
            if wk and wk != '~':
                all_workers.add(wk)
    workers = sorted(all_workers)

    result = {}
    for w in workers:
        result[f'wf.reverify_window::{w}'] = {
            'authorization expiry': resolve(wa_expiry, 'work_authorizations', ead_expiry, 'ead_cards', w),
            'reverification date': resolve(rev_done, 'reverifications', None, None, w),
        }
    for w in workers:
        result[f'wf.notice_posting::{w}'] = {
            'notice posted': resolve(notice_pinned, 'lca_notices', None, None, w),
            'notice removed': resolve(notice_unpinned, 'lca_notices', None, None, w),
            'LCA filed': resolve(lca_lodge, 'lca_filings', dol_stamp, 'dol_receipts', w),
        }

    print(json.dumps(result, indent=2))

if __name__ == '__main__':
