        lines = f.readlines()
    header = None
    data = []
    for line in lines:
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        if header is None:
            header = line.split('|')
            continue
        fields = line.split('|')
        data.append(dict(zip(header, fields)))
    return data

def convert_date(s):
    if not s:
        return None
    m, d, y = s.split('/')
    return f"{y}-{m.zfill(2)}-{d.zfill(2)}"

def get_values(rows, entity, col):
    return [r[col] for r in rows if r.get('WORKER_FILE_NUMBER') == entity and r.get(col, '')]

def resolve(values):
    if not values:
        return None, False
    if len(set(values)) > 1:
        return None, True
    return values[0], False

def fact_result(docs, entity, primary_doc, primary_col, fallback_doc=None, fallback_col=None, is_date=True):
    vals = get_values(docs[primary_doc], entity, primary_col)
    val, conflict = resolve(vals)
    if conflict:
        return 'CONFLICT'
    if val is not None:
        v = convert_date(val) if is_date else val
        return [v, primary_doc]
    if fallback_doc and fallback_col:
