import sys
import os
import json
from datetime import datetime

def parse_file(path):
    if not os.path.exists(path):
        return []
    with open(path) as f:
        lines = f.read().splitlines()
    header = None
    rows = []
    for line in lines:
        if line.startswith('#'):
            continue
        if header is None:
            header = line.split('|')
            continue
        if not line.strip():
            continue
        parts = line.split('|')
        if len(parts) == len(header):
            rows.append(dict(zip(header, parts)))
    return rows

def convert_date(s):
    if not s:
        return None
    try:
        dt = datetime.strptime(s, '%m/%d/%Y')
        return dt.strftime('%Y-%m-%d')
    except ValueError:
        return s

def get_fact_value(entity, doc_rows_list):
    for doc_name, rows, value_field in doc_rows_list:
        matching = [r for r in rows if r.get('WORKER_FILE_NUMBER') == entity]
        values = [r.get(value_field, '') for r in matching]
        non_empty = [v for v in values if v]
        if non_empty:
            converted = [convert_date(v) for v in non_empty]
            unique = set(converted)
            if len(unique) == 1:
                return [converted[0], doc_name]
            else:
                return "CONFLICT"
    return "ABSENT"

def main():
    directory = sys.argv[1]

    work_auth_rows = parse_file(os.path.join(directory, 'work_authorizations.txt'))
