MONTH_MAP = {
    'jan': 1, 'january': 1,
    'feb': 2, 'february': 2,
    'mar': 3, 'march': 3,
    'apr': 4, 'april': 4,
    'may': 5,
    'jun': 6, 'june': 6,
    'jul': 7, 'july': 7,
    'aug': 8, 'august': 8,
    'sep': 9, 'sept': 9, 'september': 9,
    'oct': 10, 'october': 10,
    'nov': 11, 'november': 11,
    'dec': 12, 'december': 12,
}

def parse_date(text):
    text = text.strip()
    match = re.match(r'(?:\w+\.,\s*)?(\w+)\s+(\d+),\s*(\d+)', text)
    if match:
        month_str = match.group(1).lower().rstrip('.')
        day = int(match.group(2))
        year = int(match.group(3))
        month = MONTH_MAP.get(month_str)
        if month:
            return f"{year:04d}-{month:02d}-{day:02d}"
    return None

def clean_html(text):
    text = re.sub(r'<[^>]+>', '', text)
    text = html.unescape(text)
    return text.strip()

def parse_html_sheets(html_text):
    sheets = []
    for article_match in re.finditer(r'<article class="sheet"[^>]*>(.*?)</article>', html_text, re.DOTALL):
        article_content = article_match.group(1)
        sheet_data = {}
        for row_match in re.finditer(r'<tr>\s*<th>(.*?)</th>\s*<td([^>]*)>(.*?)</td>\s*</tr>', article_content, re.DOTALL):
            field_name = clean_html(row_match.group(1))
            td_attrs = row_match.group(2)
            field_value = clean_html(row_match.group(3))
            if 'void' in td_attrs or 'left blank' in field_value.lower():
                sheet_data[field_name] = None
            else:
                sheet_data[field_name] = field_value
        if sheet_data:
            sheets.append(sheet_data)
    return sheets

def build_doc_index(sheets, relevant_fields):
    index = {}
    for sheet in sheets:
        badge = sheet.get('Staff badge')
        if not badge:
            continue
        if badge not in index:
            index[badge] = {}
        for field in relevant_fields:
            if field in sheet and sheet[field] is not None:
                if field not in index[badge]:
                    index[badge][field] = []
                index[badge][field].append(sheet[field])
    return index

def get_fact_value(doc_index, doc_name, field_name, entity, parse_func=None):
    if entity not in doc_index:
        return None
    field_values = doc_index[entity].get(field_name, [])
    if not field_values:
        return None
    if parse_func:
        parsed_values = [v for v in (parse_func(val) for val in field_values) if v is not None]
    else:
        parsed_values = list(field_values)
    if not parsed_values:
        return None
    unique_values = set(parsed_values)
    if len(unique_values) > 1:
        return "CONFLICT"
    return [parsed_values[0], doc_name]

def resolve_fact(primary_doc, primary_field, fallback_doc, fallback_field, entity, doc_indices, parse_func=None):
    result = get_fact_value(doc_indices.get(primary_doc, {}), primary_doc, primary_field, entity, parse_func)
    if result is not None:
        return result
    if fallback_doc:
        result = get_fact_value(doc_indices.get(fallback_doc, {}), fallback_doc, fallback_field, entity, parse_func)
        if result is not None:
            return result
    return "ABSENT"

def main():
    dir_path = sys.argv[1]

    doc_field_map = {
        'work_authorizations': ['Evidence expires'],
        'ead_cards': ['EAD valid to'],
        'reverifications': ['Supplement B signed on'],
        'lca_notices': ['Notice first displayed', 'Notice withdrawn from display'],
        'lca_filings': ['Submitted through FLAG'],
        'dol_receipts': ['Agency receipt notice dated'],
    }

    doc_indices = {}
    for doc_name, fields in doc_field_map.items():
        filepath = os.path.join(dir_path, doc_name + '.html')
        with open(filepath, 'r', encoding='utf-8') as f:
            html_text = f.read()
        sheets = parse_html_sheets(html_text)
        doc_indices[doc_name] = build_doc_index(sheets, fields)

    entities = [f'E-407{i:02d}' for i in range(1, 17)]

    result = {}

    for entity in entities:
        reverify_key = f'wf.reverify_window::{entity}'
        result[reverify_key] = {}
        result[reverify_key]['authorization expiry'] = resolve_fact(
            'work_authorizations', 'Evidence expires',
            'ead_cards', 'EAD valid to',
            entity, doc_indices, parse_date
        )
        result[reverify_key]['reverification date'] = resolve_fact(
            'reverifications', 'Supplement B signed on',
            None, None,
            entity, doc_indices, parse_date
        )

        notice_key = f'wf.notice_posting::{entity}'
        result[notice_key] = {}
        result[notice_key]['notice posted'] = resolve_fact(
            'lca_notices', 'Notice first displayed',
            None, None,
            entity, doc_indices, parse_date
        )
        result[notice_key]['notice removed'] = resolve_fact(
            'lca_notices', 'Notice withdrawn from display',
            None, None,
            entity, doc_indices, parse_date
        )
        result[notice_key]['LCA filed'] = resolve_fact(
            'lca_filings', 'Submitted through FLAG',
            'dol_receipts', 'Agency receipt notice dated',
            entity, doc_indices, parse_date
        )

    print(json.dumps(result, indent=2))

if __name__ == '__main__':
    main()
