    month_str = month_str.rstrip('.')
    month = MONTHS.get(month_str)
    if month is None:
        return None
    return f"{int(year):04d}-{month:02d}-{int(day):02d}"

def parse_sheets(html_content, field_name):
    result = {}
    sheets = re.findall(r'<article class="sheet"[^>]*>(.*?)</article>', html_content, re.DOTALL)
