import re
import json
from datetime import date, timedelta

def parse_sql_file(filepath):
    with open(filepath, 'r') as f:
        content = f.read()
    records = []
    insert_pattern = re.compile(
        r'INSERT\s+INTO\s+\w+\s*\(([^)]+)\)\s*VALUES\s*(.*?);',
        re.IGNORECASE | re.DOTALL
    )
    for match in insert_pattern.finditer(content):
        cols_str = match.group(1).strip()
        values_section = match.group(2)
        columns = [c.strip() for c in cols_str.split(',')]
        tuples = extract_tuples(values_section)
        for tuple_str in tuples:
            values = parse_value_list(tuple_str)
            if len(values) == len(columns):
                records.append(dict(zip(columns, values)))
    return records

def extract_tuples(s):
    tuples = []
    i = 0
    while i < len(s):
        if s[i] == '(':
            depth = 1
            j = i + 1
            in_string = False
            while j < len(s) and depth > 0:
                if s[j] == "'" and not in_string:
                    in_string = True
                elif s[j] == "'" and in_string:
                    if j + 1 < len(s) and s[j+1] == "'":
                        j += 1
                    else:
                        in_string = False
                elif s[j] == '(' and not in_string:
                    depth += 1
                elif s[j] == ')' and not in_string:
                    depth -= 1
                j += 1
            if depth == 0:
                tuples.append(s[i+1:j-1])
                i = j
            else:
                i += 1
        else:
            i += 1
    return tuples

def parse_value_list(s):
    values = []
    i = 0
    n = len(s)
    while i < n:
        while i < n and s[i] in ' \t\n\r':
            i += 1
        if i >= n:
            break
        if s[i] == "'":
            i += 1
            val = ''
            while i < n:
                if s[i] == "'":
                    if i + 1 < n and s[i+1] == "'":
                        val += "'"
                        i += 2
                    else:
                        i += 1
                        break
                else:
                    val += s[i]
                    i += 1
            values.append(val)
        else:
            j = i
            while j < n and s[j] != ',':
                j += 1
            token = s[i:j].strip()
            if token.upper() == 'NULL':
                values.append(None)
            else:
                values.append(token)
            i = j
        while i < n and s[i] in ' \t\n\r':
            i += 1
        if i < n and s[i] == ',':
            i += 1
    return values

def epd_to_date(epd_str):
    epd = int(epd_str)
    d = date(1970, 1, 1) + timedelta(days=epd)
    return d.isoformat()

def get_values_for_entity(records, entity, column):
    values = []
    for rec in records:
        if rec.get('wkr_code') == entity:
            val = rec.get(column)
            if val is not None:
                values.append(val)
    return values

def resolve_fact(primary_records, primary_column, primary_doc,
                  fallback_records, fallback_column, fallback_doc, entity):
    primary_values = get_values_for_entity(primary_records, entity, primary_column)
    if primary_values:
        distinct = set(primary_values)
        if len(distinct) > 1:
            return ('CONFLICT', None)
        return (primary_values[0], primary_doc)
    if fallback_records is not None and fallback_column is not None:
        fallback_values = get_values_for_entity(fallback_records, entity, fallback_column)
        if fallback_values:
            distinct = set(fallback_values)
            if len(distinct) > 1:
                return ('CONFLICT', None)
            return (fallback_values[0], fallback_doc)
    return (None, None)

def format_fact(val, doc):
    if val == 'CONFLICT':
        return 'CONFLICT'
    if val is None:
        return 'ABSENT'
    return [epd_to_date(val), doc]

def main():
    dir_path = sys.argv[1]
    dol_receipts = parse_sql_file(os.path.join(dir_path, 'dol_receipts.sql'))
    ead_cards = parse_sql_file(os.path.join(dir_path, 'ead_cards.sql'))
    lca_filings = parse_sql_file(os.path.join(dir_path, 'lca_filings.sql'))
    lca_notices = parse_sql_file(os.path.join(dir_path, 'lca_notices.sql'))
    reverifications = parse_sql_file(os.path.join(dir_path, 'reverifications.sql'))
    work_authorizations = parse_sql_file(os.path.join(dir_path, 'work_authorizations.sql'))
    result = {}
    entities = [f'E-408{i:02d}' for i in range(1, 17)]
    for entity in entities:
        pair_id = f'wf.reverify_window::{entity}'
        facts = {}
        val, doc = resolve_fact(
            work_authorizations, 'eligibility_doc_lapse_epd', 'work_authorizations',
            ead_cards, 'ead_lapse_epd', 'ead_cards', entity)
        facts['authorization expiry'] = format_fact(val, doc)
        val, doc = resolve_fact(
            reverifications, 'i9_redo_done_epd', 'reverifications',
            None, None, None, entity)
        facts['reverification date'] = format_fact(val, doc)
        result[pair_id] = facts
    for entity in entities:
        pair_id = f'wf.notice_posting::{entity}'
        facts = {}
        val, doc = resolve_fact(
            lca_notices, 'board_pinned_epd', 'lca_notices',
