def parse_values(values_str):
    parts = []
    current = ''
    in_string = False
    for char in values_str:
        if char == "'":
            in_string = not in_string
            current += char
        elif char == ',' and not in_string:
            parts.append(current.strip())
            current = ''
        else:
            current += char
    if current.strip():
        parts.append(current.strip())
    return [parse_value(p) for p in parts]

def parse_value(val_str):
    val_str = val_str.strip()
    if val_str.upper() == 'NULL':
        return None
    if val_str.startswith("'") and val_str.endswith("'"):
        return val_str[1:-1]
    try:
        return int(val_str)
    except ValueError:
        return val_str

def epd_to_date(epd):
    return (date(1970, 1, 1) + timedelta(days=epd)).isoformat()

def get_values_for_entity(records, value_col, entity, entity_col='wkr_code'):
    values = []
    for record in records:
        if record.get(entity_col) == entity:
            val = record.get(value_col)
            if val is not None:
                values.append(val)
    return values

def resolve_fact(primary_records, primary_value_col, primary_doc_name,
                  fallback_records, fallback_value_col, fallback_doc_name,
                  entity):
    primary_values = get_values_for_entity(primary_records, primary_value_col, entity)

    if primary_values:
        unique_values = set(primary_values)
        if len(unique_values) > 1:
            return ('CONFLICT', None)
        return (list(unique_values)[0], primary_doc_name)

    if fallback_records is not None:
        fallback_values = get_values_for_entity(fallback_records, fallback_value_col, entity)
        if fallback_values:
            unique_values = set(fallback_values)
            if len(unique_values) > 1:
                return ('CONFLICT', None)
            return (list(unique_values)[0], fallback_doc_name)

    return (None, None)

def format_fact(result):
    value, doc = result
    if value is None:
        return "ABSENT"
    if value == 'CONFLICT':
        return "CONFLICT"
    return [epd_to_date(value), doc]

def main():
    dir_path = sys.argv[1]

    dol_receipts = parse_sql_file(os.path.join(dir_path, 'dol_receipts.sql'))
    ead_cards = parse_sql_file(os.path.join(dir_path, 'ead_cards.sql'))
    lca_filings = parse_sql_file(os.path.join(dir_path, 'lca_filings.sql'))
    lca_notices = parse_sql_file(os.path.join(dir_path, 'lca_notices.sql'))
    reverifications = parse_sql_file(os.path.join(dir_path, 'reverifications.sql'))
    work_authorizations = parse_sql_file(os.path.join(dir_path, 'work_authorizations.sql'))

    entities = [f'E-409{i:02d}' for i in range(1, 17)]
    result = {}

    for entity in entities:
        key = f'wf.reverify_window::{entity}'
        result[key] = {}

        auth_result = resolve_fact(
            work_authorizations, 'eligibility_doc_lapse_epd', 'work_authorizations',
            ead_cards, 'ead_lapse_epd', 'ead_cards',
            entity
        )
        result[key]['authorization expiry'] = format_fact(auth_result)

        reverify_result = resolve_fact(
            reverifications, 'i9_redo_done_epd', 'reverifications',
            None, None, None,
            entity
        )
        result[key]['reverification date'] = format_fact(reverify_result)

    for entity in entities:
        key = f'wf.notice_posting::{entity}'
        result[key] = {}

        posted_result = resolve_fact(
            lca_notices, 'board_pinned_epd', 'lca_notices',
            None, None, None,
            entity
        )
        result[key]['notice posted'] = format_fact(posted_result)

        removed_result = resolve_fact(
            lca_notices, 'board_unpinned_epd', 'lca_notices',
            None, None, None,
            entity
        )
        result[key]['notice removed'] = format_fact(removed_result)

        lca_filed_result = resolve_fact(
            lca_filings, 'lca_lodge_epd', 'lca_filings',
            dol_receipts, 'agency_stamp_epd', 'dol_receipts',
            entity
        )
        result[key]['LCA filed'] = format_fact(lca_filed_result)

    print(json.dumps(result, indent=2))

if __name__ == '__main__':
    main()
