import sys
import os
import json

def parse_edi_segments(filepath):
    with open(filepath, 'r') as f:
        content = f.read()
    segments = [s.strip() for s in content.split('~') if s.strip()]
    return segments

def extract_dtp_values(filepath, dtp_qualifier):
    if not os.path.exists(filepath):
        return {}
    segments = parse_edi_segments(filepath)
    records = {}
    current_ei = None
    for seg in segments:
        parts = seg.split('*')
        tag = parts[0]
        if tag == 'LX':
            current_ei = None
        elif tag == 'REF' and len(parts) >= 3 and parts[1] == 'EI':
            current_ei = parts[2]
        elif tag == 'DTP' and len(parts) >= 4 and parts[1] == dtp_qualifier and parts[2] == 'D8':
            if current_ei:
                date_str = parts[3]
                formatted = f"{date_str[:4]}-{date_str[4:6]}-{date_str[6:8]}"
                records.setdefault(current_ei, []).append(formatted)
    return records

def collect_entity_ids(directory):
    entity_ids = set()
    files = ['work_authorizations.edi', 'ead_cards.edi', 'reverifications.edi',
             'lca_notices.edi', 'lca_filings.edi', 'dol_receipts.edi', 'hr_roster.edi']
    for filename in files:
        filepath = os.path.join(directory, filename)
        if not os.path.exists(filepath):
            continue
        segments = parse_edi_segments(filepath)
        for seg in segments:
            parts = seg.split('*')
            if parts[0] == 'REF' and len(parts) >= 3 and parts[1] == 'EI':
                entity_ids.add(parts[2])
    return sorted(entity_ids)

def resolve_with_fallback(primary_records, primary_doc, fallback_records, fallback_doc, ei):
    if ei in primary_records and primary_records[ei]:
        values = primary_records[ei]
        unique = set(values)
        if len(unique) == 1:
            return [values[0], primary_doc]
        else:
            return "CONFLICT"
    if fallback_records and ei in fallback_records and fallback_records[ei]:
        values = fallback_records[ei]
        unique = set(values)
        if len(unique) == 1:
            return [values[0], fallback_doc]
        else:
            return "CONFLICT"
    return "ABSENT"

def resolve_single(records, doc, ei):
    if ei in records and records[ei]:
        values = records[ei]
        unique = set(values)
        if len(unique) == 1:
            return [values[0], doc]
        else:
            return "CONFLICT"
    return "ABSENT"

def main():
    directory = sys.argv[1]

    wa_expiry = extract_dtp_values(os.path.join(directory, 'work_authorizations.edi'), '036')
    ead_expiry = extract_dtp_values(os.path.join(directory, 'ead_cards.edi'), '438')
    reverify_date = extract_dtp_values(os.path.join(directory, 'reverifications.edi'), '572')

    notice_posted = extract_dtp_values(os.path.join(directory, 'lca_notices.edi'), '196')
    notice_removed = extract_dtp_values(os.path.join(directory, 'lca_notices.edi'), '197')
    lca_filed = extract_dtp_values(os.path.join(directory, 'lca_filings.edi'), '640')
    dol_receipt = extract_dtp_values(os.path.join(directory, 'dol_receipts.edi'), '009')

    entities = collect_entity_ids(directory)

    result = {}

    for ei in entities:
        reverify_key = f'wf.reverify_window::{ei}'
        result[reverify_key] = {
            'authorization expiry': resolve_with_fallback(wa_expiry, 'work_authorizations', ead_expiry, 'ead_cards', ei),
            'reverification date': resolve_single(reverify_date, 'reverifications', ei)
        }

    for ei in entities:
        notice_key = f'wf.notice_posting::{ei}'
        result[notice_key] = {
            'notice posted': resolve_single(notice_posted, 'lca_notices', ei),
            'notice removed': resolve_single(notice_removed, 'lca_notices', ei),
            'LCA filed': resolve_with_fallback(lca_filed, 'lca_filings', dol_receipt, 'dol_receipts', ei)
        }

    print(json.dumps(result, indent=2))

if __name__ == '__main__':
    main()
