Looking at this problem, I need to:
1. Parse EDI files containing LX loops with entity keys (REF*EI) and date segments (DTP)
2. Extract specific facts based on decision rules with fallback documents
3. Detect conflicts (multiple different values in the same document for the same entity)
4. Output JSON with values, document sources, ABSENT, or CONFLICT

Key mappings:
- `authorization expiry`: work_authorizations DTP*036 → fallback ead_cards DTP*438
- `reverification date`: reverifications DTP*572 (no fallback)
- `notice posted`: lca_notices DTP*196 (no fallback)
- `notice removed`: lca_notices DTP*197 (no fallback)
- `LCA filed`: lca_filings DTP*640 → fallback dol_receipts DTP*009

```python
import sys
import os
import json

def parse_edi(filepath):
    with open(filepath, 'r') as f:
        content = f.read()
    segments = content.split('~')
    loops = []
    current_loop = None
    for seg in segments:
        seg = seg.strip()
        if not seg:
            continue
        elements = seg.split('*')
        tag = elements[0]
        if tag == 'LX':
            if current_loop is not None:
                loops.append(current_loop)
            current_loop = []
        elif current_loop is not None:
            current_loop.append(elements)
    if current_loop is not None:
        loops.append(current_loop)
    return loops

def extract_values(loops, entity_id, target_tag, target_qualifier):
    values = []
    for loop in loops:
        ei = None
        target = None
        for seg in loop:
            if seg[0] == 'REF' and len(seg) > 2 and seg[1] == 'EI':
                ei = seg[2]
            if seg[0] == target_tag and len(seg) > 1 and seg[1] == target_qualifier:
                if len(seg) > 3:
                    target = seg[3]
        if ei == entity_id and target is not None:
            values.append(target)
    return values

def format_date(d):
    return f"{d[:4]}-{d[4:6]}-{d[6:8]}"

def resolve_with_fallback(primary_doc, primary_vals, fallback_doc, fallback_vals, formatter):
    if primary_vals:
        if len(set(primary_vals)) > 1:
            return "CONFLICT"
        return [formatter(primary_vals[0]), primary_doc]
    elif fallback_vals:
        if len(set(fallback_vals)) > 1:
            return "CONFLICT"
        return [formatter(fallback_vals[0]), fallback_doc]
    else:
        return "ABSENT"

def resolve_single(doc, vals, formatter):
    if vals:
        if len(set(vals)) > 1:
            return "CONFLICT"
        return [formatter(vals[0]), doc]
    else:
        return "ABSENT"

def main():
    directory = sys.argv[1]

    files = {
        'dol_receipts': 'dol_receipts.edi',
        'ead_cards': 'ead_cards.edi',
        'hr_roster': 'hr_roster.edi',
        'lca_filings': 'lca_filings.edi',
        'lca_notices': 'lca_notices.edi',
        'reverifications': 'reverifications.edi',
        'work_authorizations': 'work_authorizations.edi',
    }

    parsed = {}
    for name, filename in files.items():
        filepath = os.path.join(directory, filename)
        parsed[name] = parse_edi(filepath) if os.path.exists(filepath) else []

    entities = [f"E-410{i:02d}" for i in range(1, 17)]
    result = {}

    for entity in entities:
        pair_id = f"wf.reverify_window::{entity}"
        wa_vals = extract_values(parsed.get('work_authorizations', []), entity, 'DTP', '036')
        ead_vals = extract_values(parsed.get('ead_cards', []), entity, 'DTP', '438')
        auth_expiry = resolve_with_fallback('work_authorizations', wa_vals, 'ead_cards', ead_vals, format_date)

        rev_vals = extract_values(parsed.get('reverifications', []), entity, 'DTP', '572')
        rev_date = resolve_single('reverifications', rev_vals, format_date)

        result[pair_id] = {
            'authorization expiry': auth_expiry,
            'reverification date': rev_date,
        }

    for entity in entities:
        pair_id = f"wf.notice_posting::{entity}"
        posted_vals = extract_values(parsed.get('lca_notices', []), entity, 'DTP', '196')
        notice_posted = resolve_single('lca_notices', posted_vals, format_date)

        removed_vals = extract_values(parsed.get('lca_notices', []), entity, 'DTP', '197')
        notice_removed = resolve_single('lca_notices', removed_vals, format_date)

        lca_vals = extract_values(parsed.get('lca_filings', []), entity, 'DTP', '640')
        dol_vals = extract_values(parsed.get('dol_receipts', []), entity, 'DTP', '009')
        lca_filed = resolve_with_fallback('lca_filings', lca_vals, 'dol_receipts', dol_vals, format_date)

        result[pair_id] = {
            'notice posted': notice_posted,
            'notice removed': notice_removed,
            'LCA filed': lca_filed,
        }

    print(json.dumps(result, indent=2))

if __name__ == '__main__':
    main()
